1	<!doctype html>
2	<!--
3	  Squelette de deck de slides (HTML interactif), forme exécutable de Design-system §5.7.
4	  Classe d'artefact DISTINCTE des visuels PNG §5.0 : deck multi-slides, responsive 16:9,
5	  ouvert au navigateur (jamais rendu en PNG pour livraison ; PNG seulement pour le gate QA).
6	  L'INSTANCE remplie vit dans 02-Areas/Éditorial/assets/slides-<sujet>.html (par-pièce, ADR-006),
7	  jamais dans Brand/. Composée par le skill add-editorial-slides depuis la piece.
8	
9	  Tokens §1.1/§1.3, fonts §2.1, wordmark = logo/sources/wordmark-color-light.svg (inliné).
10	  Layout auto-layout CSS (flex/grid), aucune coordonnée à la main sauf les signatures
11	  (barre accent haut-gauche, wordmark haut-droite).
12	
13	  Slide-types (catalogue §5.7) : title · bullets · cards · table · flow · callout · compare · probe · layers.
14	  Sélection du type par intention : table heuristique contenu→format §5.7 (archétypes).
15	  Navigation : flèches / clic (gauche-droite) / espace ; plein écran : touche f.
16	  Gate QA : ouvrir `slides-<sujet>.html?slide=N` affiche la slide N seule (chrome masqué) →
17	  node Brand/_pipeline/render-html.mjs <html>?slide=N <out.png> 1280 720 pour inspection.
18	
19	  Wordmark haut-droite (.slide-logo) sur TOUTES les slides sauf title (la cover porte le grand wordmark).
20	  Le skill remplit UNIQUEMENT la région délimitée par les marqueurs slot:slides:start / slot:slides:end.
21	  Les slides ci-dessous sont une référence illustrative (une par slide-type), pas une limite.
22	-->
23	<html lang="fr">
24	<head>
25	<meta charset="utf-8">
26	<meta name="viewport" content="width=device-width, initial-scale=1">
27	<title>BGA - deck de slides</title>
28	<link rel="preconnect" href="https://fonts.googleapis.com">
29	<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
30	<link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;700&display=swap" rel="stylesheet">
31	<style>
32	  /* ====== Tokens (Design-system §1.1/§1.3) ====== */
33	  :root {
34	    --bg:#FAF6EE; --surface:#FFFDF8; --indigo:#261961; --muted:#5C5278;
35	    --accent:#C68A14; --accent-soft:#F2E3B8; --border:#E8DEC8; --warning:#8A5A0A;
36	    --indigo-soft:rgba(38,25,97,0.08);
37	    --accent-halo:rgba(198,138,20,0.22); --accent-glow:rgba(198,138,20,0.45);
38	    --font-display:'Manrope',system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;
39	    --font-mono:'JetBrains Mono',"SF Mono",Consolas,monospace;
40	  }
41	  * { margin:0; padding:0; box-sizing:border-box; }
42	  html, body { height:100%; }
43	  body {
44	    font-family:var(--font-display); color:var(--indigo);
45	    background-color:var(--bg);
46	    background-image:radial-gradient(circle, var(--indigo-soft) 1px, transparent 1px);
47	    background-size:22px 22px;
48	    overflow:hidden;
49	  }
50	  /* ====== CADRE générique slide (§5.7) ====== */
51	  .slide { position:fixed; inset:0; display:none; flex-direction:column; justify-content:center; padding:6vh 9vw; gap:2.4vh; }
52	  .slide.active { display:flex; }
53	  .accent-bar { position:absolute; top:5vh; left:9vw; width:96px; height:5px; background:var(--accent); }
54	  /* signature wordmark coin haut-droit, toutes slides sauf title (§5.7) */
55	  .slide-logo { position:absolute; top:4.2vh; right:9vw; display:flex; align-items:baseline; }
56	  .slide-logo .bga { font-weight:800; font-size:clamp(18px,2.5vh,30px); letter-spacing:-1px; color:var(--indigo); }
57	  .slide-logo .dot { width:6px; height:6px; border-radius:50%; background:var(--accent); align-self:center; margin:0 .34em; }
58	  .slide-logo .co { font-weight:500; font-size:clamp(11px,1.5vh,19px); color:var(--muted); }
59	  /* ====== Primitives texte ====== */
60	  .kicker { font-family:var(--font-mono); font-size:clamp(14px,1.7vw,26px); font-weight:700; letter-spacing:4px; text-transform:uppercase; color:var(--warning); }
61	  h1 { font-size:clamp(40px,7vw,104px); font-weight:700; line-height:1.08; }
62	  h2 { font-size:clamp(30px,4.4vw,64px); font-weight:700; line-height:1.12; }
63	  /* surligneur « peint depuis le bas » (technique §5.8, partagée avec carousel + event-banner) :
64	     le haut non peint laisse respirer la ligne au-dessus sur un titre multi-lignes */
65	  .hl { background-image:linear-gradient(var(--accent-soft),var(--accent-soft)); background-size:100% 82%; background-position:0 100%; background-repeat:no-repeat; border-radius:10px; padding:0 .12em; font-weight:800; box-decoration-break:clone; -webkit-box-decoration-break:clone; }
66	  .lead { font-size:clamp(18px,2.4vw,38px); font-weight:500; color:var(--muted); line-height:1.45; max-width:32ch; }
67	  .sub { font-size:clamp(16px,2vw,32px); font-weight:500; color:var(--muted); }
68	  code { font-family:var(--font-mono); background:var(--accent-soft); color:var(--indigo); border-radius:6px; padding:.04em .3em; font-size:.92em; }
69	  /* ====== slide-type: bullets ====== */
70	  ul { list-style:none; display:flex; flex-direction:column; gap:1.6vh; }
71	  li { font-size:clamp(17px,2.2vw,34px); line-height:1.3; }
72	  li b { font-weight:700; color:var(--indigo); }
73	  /* ====== slide-type: cards ====== */
74	  .cards { display:flex; gap:2vw; flex-wrap:wrap; }
75	  .card { flex:1 1 0; min-width:220px; background:var(--surface); border:1px solid var(--border); border-radius:16px; padding:3vh 2vw; display:flex; flex-direction:column; gap:1.2vh; }
76	  .card .tag { font-family:var(--font-mono); font-size:clamp(12px,1.2vw,18px); font-weight:700; color:var(--accent); letter-spacing:2px; text-transform:uppercase; }
77	  .card .t { font-size:clamp(18px,2vw,30px); font-weight:700; }
78	  .card .d { font-size:clamp(14px,1.4vw,22px); color:var(--muted); line-height:1.4; }
79	  /* ====== slide-type: table ====== */
80	  table { border-collapse:collapse; width:100%; font-size:clamp(12px,1.45vw,24px); }
81	  th, td { text-align:left; padding:1.1vh 1vw; border-bottom:1px solid var(--border); }
82	  th { font-family:var(--font-mono); font-size:.82em; text-transform:uppercase; letter-spacing:1px; color:var(--warning); }
83	  tbody tr:last-child td { border-bottom:none; background:var(--accent-soft); }
84	  td .em { color:var(--indigo); font-weight:700; }
85	  /* ====== slide-type: flow ====== */
86	  .flow { display:flex; gap:1vw; flex-wrap:wrap; align-items:center; font-size:clamp(18px,2.6vw,40px); font-weight:700; }
87	  .flow .step { background:var(--surface); border:1px solid var(--border); border-radius:12px; padding:1.2vh 1.4vw; }
88	  .flow .arrow { color:var(--accent); }
89	  /* ====== slide-type: callout (encart définition / note dense) ====== */
90	  .callout { font-size:clamp(13px,1.5vw,24px); color:var(--muted); line-height:1.4; max-width:72ch; }
91	  .callout b { color:var(--warning); font-weight:700; }
92	  /* ====== slide-type: probe (CTA discret / sondage chat live) ====== */
93	  .probe { font-size:clamp(16px,2.2vw,34px); font-weight:500; color:var(--muted); line-height:1.4; max-width:40ch; }
94	  .probe b { color:var(--indigo); font-weight:700; }
95	  /* ====== bullets - variante puces visibles (marqueur accent décoratif) ====== */
96	  .puces li { position:relative; padding-left:1.4em; }
97	  .puces li::before { content:'•'; position:absolute; left:0; color:var(--accent); font-weight:800; }
98	  /* ====== slide-type: def (définition détachée en aside, pleine largeur, alignée gauche, au-dessus du chrome de nav) ======
99	     informe sans surcharger le bloc principal ; 1 ligne par idée. Distinct du callout (encart inline). */
100	  .slide-def { position:absolute; left:9vw; right:9vw; bottom:7vh; padding-left:1vw; border-left:3px solid var(--accent); }
101	  .slide-def .dt { font-family:var(--font-mono); font-size:clamp(11px,1.2vw,18px); font-weight:700; letter-spacing:1px; text-transform:uppercase; color:var(--warning); margin-bottom:.6vh; }
102	  .slide-def .dl { font-size:clamp(13px,1.45vw,22px); color:var(--muted); line-height:1.42; }
103	  .slide-def .dl b { color:var(--indigo); font-weight:700; }
104	  /* ====== slide-type: compare (2 silhouettes + flèche ; largeur de bande = volumétrie) ====== */
105	  .compare-frame { display:grid; grid-template-columns:auto 1fr; grid-template-rows:auto auto; column-gap:1vw; row-gap:.7vh; width:100%; }
106	  .compare { grid-column:2; grid-row:1; display:flex; align-items:center; justify-content:center; gap:2.4vw; width:100%; }
107	  .compare-col { display:flex; flex-direction:column; align-items:center; width:25vw; }
108	  .compare-col .cap { font-family:var(--font-mono); font-size:clamp(11px,1.2vw,20px); font-weight:700; letter-spacing:1px; text-transform:uppercase; color:var(--warning); margin-bottom:1vh; }
109	  .bands { width:100%; display:flex; flex-direction:column; gap:3px; }
110	  .band { position:relative; height:7.4vh; display:flex; align-items:center; justify-content:center; }
111	  .band .fill { position:absolute; inset:0; background:var(--accent-soft); }
112	  .band.hot .fill { background:var(--accent); }
113	  .band .lbl { position:relative; z-index:1; font-weight:700; font-size:clamp(13px,1.5vw,26px); color:var(--indigo); } /* texte indigo : blanc-sur-accent INTERDIT §1.2 */
114	  .compare .arrow { font-size:clamp(30px,4vw,60px); color:var(--accent); font-weight:800; }
115	  /* bibliothèque de silhouettes nommées (clip-paths) : largeur de bande ∝ volumétrie par étage */
116	  .sil-pyramid .band:nth-child(1) .fill { clip-path:polygon(44% 0,56% 0,70% 100%,30% 100%); }
117	  .sil-pyramid .band:nth-child(2) .fill { clip-path:polygon(30% 0,70% 0,85% 100%,15% 100%); }
118	  .sil-pyramid .band:nth-child(3) .fill { clip-path:polygon(15% 0,85% 0,100% 100%,0 100%); }
119	  .sil-diamond .band:nth-child(1) .fill { clip-path:polygon(46% 0,54% 0,74% 100%,26% 100%); }
120	  .sil-diamond .band:nth-child(2) .fill { clip-path:polygon(26% 0,74% 0,100% 50%,74% 100%,26% 100%,0 50%); }
121	  .sil-diamond .band:nth-child(3) .fill { clip-path:polygon(26% 0,74% 0,54% 100%,46% 100%); }
122	  /* axes partagés OPTIONNELS : Y = complexité/coût (vers le haut) · X = volumétrie (largeur des bandes) */
123	  .compare-frame .axis-y { grid-column:1; grid-row:1; display:flex; align-items:stretch; gap:.5vw; }
124	  .compare-frame .axis-x { grid-column:2; grid-row:2; display:flex; flex-direction:column; gap:.5vh; }
125	  .axis-y .line { width:3px; align-self:stretch; background:linear-gradient(to top,var(--border),var(--accent)); position:relative; }
126	  .axis-y .line::after { content:'▲'; position:absolute; top:-.9em; left:50%; transform:translateX(-50%); color:var(--accent); font-size:.6em; line-height:1; }
127	  .axis-x .line { height:3px; width:100%; background:linear-gradient(to right,var(--border),var(--accent)); position:relative; }
128	  .axis-x .line::after { content:'▶'; position:absolute; right:-.5em; top:50%; transform:translateY(-50%); color:var(--accent); font-size:.6em; line-height:1; }
129	  .axis-lab { font-family:var(--font-mono); font-weight:700; font-size:clamp(11px,1.2vw,20px); letter-spacing:2px; text-transform:uppercase; color:var(--warning); }
130	  .axis-y .axis-lab { writing-mode:vertical-rl; transform:rotate(180deg); text-align:center; align-self:center; }
131	  .axis-x .axis-lab { text-align:center; }
132	  /* ====== slide-type: layers (§5.7) - carte de strates : une bande par couche, positionnement dans une stack ====== */
133	  .layers { display:flex; flex-direction:column; gap:1.3vh; width:100%; }
134	  .layer { position:relative; background:var(--surface); border:1px solid var(--border); border-radius:14px; padding:1.9vh 1.8vw; display:flex; align-items:center; gap:1.6vw; }
135	  .layer.opt { border-style:dashed; } /* couche optionnelle */
136	  .layer .lv { font-family:var(--font-mono); font-size:clamp(11px,1.1vw,18px); font-weight:700; letter-spacing:1px; text-transform:uppercase; color:var(--warning); min-width:9ch; }
137	  .layer .body { display:flex; flex-direction:column; gap:.3vh; }
138	  .layer .nm { font-size:clamp(18px,2vw,32px); font-weight:700; color:var(--indigo); }
139	  .layer .ex { font-size:clamp(13px,1.35vw,21px); color:var(--muted); }
140	  .layer .chip { margin-left:auto; background:var(--accent-soft); color:var(--indigo); font-weight:800; border-radius:8px; padding:.5vh .9vw; font-size:clamp(14px,1.6vw,26px); white-space:nowrap; } /* surligner une couche : indigo sur accent-soft, 11.42:1 §1.2 */
141	  .layer .note { margin-left:auto; font-size:clamp(12px,1.25vw,20px); color:var(--warning); font-weight:700; max-width:20ch; text-align:right; line-height:1.25; } /* caption latérale */
142	  /* ====== identité + chrome de navigation ====== */
143	  .wordmark { width:clamp(180px,18vw,320px); height:auto; margin-top:3vh; }
144	  .counter { position:fixed; bottom:3vh; right:4vw; font-family:var(--font-mono); font-size:clamp(11px,1.1vw,16px); color:var(--muted); }
145	  .hint { position:fixed; bottom:3vh; left:4vw; font-family:var(--font-mono); font-size:clamp(11px,1.1vw,16px); color:var(--muted); }
146	  body.capture .counter, body.capture .hint { display:none; } /* gate QA : ?slide=N masque le chrome */
147	  /* ====== mode pointeur (présentation) ======
148	     Le clic cesse de naviguer : on peut désigner et souligner à la souris sans changer de slide.
149	     Ambre décoratif (§1.2 : jamais du texte), donc conforme en tant que marqueur. */
150	  body.laser { cursor:none; }
151	  .laser-dot { position:fixed; z-index:9; width:18px; height:18px; margin:-9px 0 0 -9px; border-radius:50%; background:var(--accent); box-shadow:0 0 0 6px var(--accent-halo), 0 0 18px 4px var(--accent-glow); pointer-events:none; display:none; }
152	  /* taille CSS explicite : un canvas est un élément remplacé, `inset:0` seul le laisserait
153	     à sa taille intrinsèque (buffer = viewport x devicePixelRatio), donc trace décalée en HiDPI */
154	  .ink { position:fixed; left:0; top:0; width:100vw; height:100vh; z-index:8; pointer-events:none; display:none; }
155	  body.laser .laser-dot, body.laser .ink { display:block; }
156	  .hint b { color:var(--warning); font-weight:700; }
157	</style>
158	</head>
159	<body>
160	
161	<!-- slot:slides:start -->
162	<!-- Référence illustrative : une slide par slide-type. Le skill remplace toute cette région.
163	     Rappel : .slide-logo sur toutes les slides sauf title. -->
164	
165	<!-- slide-type: title (PAS de .slide-logo : la cover porte le grand wordmark) -->
166	<section class="slide active">
167	  <div class="accent-bar"></div>
168	  <div class="kicker">Live Tech · Jour JJ mois · HHh</div>
169	  <h1>Titre du deck,<br><span class="hl">fragment clé</span></h1>
