324	<script>
325	  const slides=[...document.querySelectorAll('.slide')];
326	  const counter=document.querySelector('.counter');
327	  let i=0;
328	  function show(n){
329	    i=Math.max(0,Math.min(slides.length-1,n));
330	    slides.forEach((s,k)=>s.classList.toggle('active',k===i));
331	    counter.textContent=(i+1)+' / '+slides.length;
332	  }
333	  // Gate QA : ?slide=N affiche la slide N seule, chrome masqué (capture PNG propre).
334	  const q=new URLSearchParams(location.search).get('slide');
335	  if(q!==null){ document.body.classList.add('capture'); show(parseInt(q,10)-1); }
336	  else { show(0); }
337	  // Mode pointeur (touche l) : le clic cesse de naviguer, le curseur devient un marqueur ambre,
338	  // et maintenir le bouton trace un trait qui s'efface en ~1,2 s. Sortie par l ou Échap.
339	  const dot=document.querySelector('.laser-dot');
340	  const ink=document.querySelector('.ink');
341	  const ctx=ink.getContext('2d');
342	  const hint=document.querySelector('.hint');
343	  const HINT_NAV='← → naviguer · f plein écran · l pointeur';
344	  const HINT_LASER='<b>pointeur</b> · clic pour souligner · l ou Échap pour sortir';
345	  let laser=false, drawing=false, prev=null;
346	  function sizeInk(){
347	    const r=window.devicePixelRatio||1;
348	    ink.width=innerWidth*r; ink.height=innerHeight*r;
349	    ctx.setTransform(r,0,0,r,0,0);
350	    ctx.lineCap='round'; ctx.lineJoin='round'; ctx.lineWidth=5;
351	    ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--accent').trim();
352	  }
353	  function fade(){
354	    if(!laser) return;
355	    ctx.save();
356	    ctx.globalCompositeOperation='destination-out';
357	    ctx.fillStyle='rgba(0,0,0,0.06)';
358	    ctx.fillRect(0,0,innerWidth,innerHeight);
359	    ctx.restore();
360	    requestAnimationFrame(fade);
361	  }
362	  function setLaser(on){
363	    laser=on; drawing=false; prev=null;
364	    document.body.classList.toggle('laser',on);
365	    hint.innerHTML=on?HINT_LASER:HINT_NAV;
366	    if(on){ sizeInk(); requestAnimationFrame(fade); }
367	    else { ctx.clearRect(0,0,innerWidth,innerHeight); }
368	  }
369	  addEventListener('resize',()=>{ if(laser) sizeInk(); });
370	  document.addEventListener('mousemove',e=>{
371	    if(!laser) return;
372	    dot.style.left=e.clientX+'px'; dot.style.top=e.clientY+'px';
373	    if(drawing){
374	      if(prev){ ctx.beginPath(); ctx.moveTo(prev.x,prev.y); ctx.lineTo(e.clientX,e.clientY); ctx.stroke(); }
375	      prev={x:e.clientX,y:e.clientY};
376	    }
377	  });
378	  document.addEventListener('mousedown',e=>{ if(laser){ drawing=true; prev={x:e.clientX,y:e.clientY}; } });
379	  document.addEventListener('mouseup',()=>{ drawing=false; prev=null; });
380	  document.addEventListener('keydown',e=>{
381	    if(['ArrowRight',' ','PageDown'].includes(e.key)){e.preventDefault();show(i+1);}
382	    else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(i-1);}
383	    else if(e.key==='f'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.();}
384	    else if(e.key==='l'){setLaser(!laser);}
385	    else if(e.key==='Escape'&&laser){setLaser(false);}
386	  });
387	  document.addEventListener('click',e=>{ if(laser) return; show(i + (e.clientX < window.innerWidth*0.25 ? -1 : 1));});
388	</script>
389	</body>
390	</html>
